EDITS = [
    ("state", STATE_OLD, STATE_NEW),
    ("helpers", IDKEY_OLD, IDKEY_NEW),
    ("write", WRITE_OLD, WRITE_NEW),
    ("rlout", RLOUT_OLD, RLOUT_NEW),
    ("rlin", RLIN_OLD, RLIN_NEW),
    ("spawn", SPAWN_OLD, SPAWN_NEW),
    ("intercept", INTERCEPT_OLD, INTERCEPT_NEW),
]


def patch(src):
    """Return the patched source, or None when the layout is not recognised."""
    for name, old, new in EDITS:
        if src.count(old) != 1:
            return None, f"anchor {name!r} found {src.count(old)} times"
        src = src.replace(old, new, 1)
    return src, None


def revert(src):
    """Return the unpatched source, or None when the file is not patched."""
    for name, old, new in reversed(EDITS):
        if src.count(new) != 1:
            return None, f"edit {name!r} found {src.count(new)} times"
        src = src.replace(new, old, 1)
    return src, None


def migrate(src):
    """Bring a proxy patched by an earlier revision up to date.

    The patched text does not depend on the baseline, so an earlier
    revision's regions can be replaced with the current ones. Regions that
    the earlier revision never had are still at their baseline anchor, so
    they are applied from there.
    """
    older = {}
    for _sha, anchors in MIGRATION_ANCHORS.items():
        for name, text in anchors:
            older.setdefault(name, []).append(text)
    out = src
    applied = []
    for name, old, new in EDITS:
        if out.count(new) == 1:
            continue  # this region is already at the current revision
        # An earlier revision's text comes first: the baseline anchor is also
        # present in a patched file, and replacing only that line would leave
        # the earlier revision's region behind it.
        for text in older.get(name, []):
            if out.count(text) == 1:
                out = out.replace(text, new, 1)
                applied.append(name)
                break
        else:
            if out.count(old) == 1:
                out = out.replace(old, new, 1)
                applied.append(name)
    return (out, applied) if applied else (None, None)


def is_current(src):
    """True when every region of the current patch is in the file."""
    return all(src.count(new) == 1 for _name, _old, new in EDITS)


def main():
    if not os.path.exists(TARGET):
        sys.exit(f"not found: {TARGET}")

    src = open(TARGET).read()

    if "--revert" in sys.argv[2:]:
        reverted, error = revert(src)
        if reverted is None:
            print(f"not a patched proxy ({error}): {TARGET}")
            return 0
        backup = f"{TARGET}.bak-{time.strftime('%Y%m%dT%H%M%S')}"
        shutil.copy2(TARGET, backup)
        open(TARGET, "w").write(reverted)
        if not check_syntax(TARGET):
            shutil.copy2(backup, TARGET)
            sys.exit(f"reverted file does not parse; restored backup: {check.stderr.strip()}")
        print(f"reverted: {TARGET} (backup: {backup})")
        print("new ACP processes pick this up; restart T3 Code or open a new thread.")
        return 0

    if VERSION_MARKER in src and is_current(src):
        print(f"already patched: {TARGET}")
        return 0

    # An older revision of this patch: the file was patched from the same
    # baseline, so the current known-good file replaces it exactly.
    digest = hashlib.sha256(src.encode()).hexdigest()
    if digest in KNOWN_OLD_REVISIONS:
        known_good = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                 "mcode-acp-proxy-steer.js")
        if not os.path.exists(known_good):
            sys.exit(f"older patch revision {KNOWN_OLD_REVISIONS[digest]}, but {known_good} is missing")
        replacement = open(known_good).read()
        backup = f"{TARGET}.bak-{time.strftime('%Y%m%dT%H%M%S')}"
        shutil.copy2(TARGET, backup)
        open(TARGET, "w").write(replacement)
        if not check_syntax(TARGET):
            shutil.copy2(backup, TARGET)
            sys.exit(f"replacement does not parse; restored backup: {check.stderr.strip()}")
        print(f"migrated an older patch ({KNOWN_OLD_REVISIONS[digest]}) to the current revision: {TARGET}")
        print(f"backup: {backup}")
        print("new ACP processes pick this up; restart T3 Code or open a new thread.")
        return 0

    if MARKER in src:
        # An older revision of this patch: bring it up to date.
        migrated, applied = migrate(src)
        unknown = (
            migrated is None
            or VERSION_MARKER not in migrated
            or not is_current(migrated)
        )
        if unknown:
            sys.exit(
                f"the proxy carries a patch revision this patcher does not know "
                f"({digest}); update the patcher instead of working around it"
            )
        backup = f"{TARGET}.bak-{time.strftime('%Y%m%dT%H%M%S')}"
        shutil.copy2(TARGET, backup)
        open(TARGET, "w").write(migrated)
        if not check_syntax(TARGET):
            shutil.copy2(backup, TARGET)
            sys.exit(f"migrated file does not parse; restored backup: {check.stderr.strip()}")
        print(f"migrated an older patch to the current revision: {TARGET}")
        print(f"updated: {', '.join(applied)}")
        print(f"backup: {backup}")
        print("new ACP processes pick this up; restart T3 Code or open a new thread.")
        return 0

    patched, error = patch(src)
    if patched is None:
        sys.exit(f"unrecognised proxy layout ({error}): {TARGET}")

    backup = f"{TARGET}.bak-{time.strftime('%Y%m%dT%H%M%S')}"
    shutil.copy2(TARGET, backup)
    open(TARGET, "w").write(patched)

    if not check_syntax(TARGET):
        shutil.copy2(backup, TARGET)
        sys.exit(f"patched file does not parse; restored backup: {check.stderr.strip()}")

    print(f"patched: {TARGET} (backup: {backup})")
    print("new ACP processes pick this up; restart T3 Code or open a new thread.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())


